package com.familygrowth;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import com.fasterxml.jackson.databind.*;import java.util.UUID;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.http.MediaType;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.*;
@SpringBootTest(properties={"spring.datasource.url=${FAMILY_GROWTH_TEST_POSTGRES_URL:jdbc:h2:mem:stage8sync;MODE=PostgreSQL;DB_CLOSE_DELAY=-1}","spring.datasource.username=${FAMILY_GROWTH_TEST_POSTGRES_USER:sa}","spring.datasource.password=${FAMILY_GROWTH_TEST_POSTGRES_PASSWORD:}","spring.jpa.hibernate.ddl-auto=validate"})@AutoConfigureMockMvc@ActiveProfiles("test")class Stage8SyncApiTest{
 @Autowired MockMvc mvc;@Autowired ObjectMapper json;
 @Test void syncSnapshotUsesServerAuthorizationAndRealTaskState()throws Exception{Session p=bootstrap("Stage8家庭","468024");Session other=bootstrap("其他家庭","468025");UUID child=id(postJson("/api/v1/families/"+p.family+"/children",p.token,"{\"displayName\":\"同步孩子\",\"birthDate\":\"2017-01-01\",\"ageStage\":\"CHILD_6_9\"}",201));UUID plan=id(postJson("/api/v1/families/"+p.family+"/children/"+child+"/plans",p.token,"{\"title\":\"同步计划\",\"startDate\":\"2026-08-25\"}",201));UUID goal=id(postJson("/api/v1/families/"+p.family+"/plans/"+plan+"/goals",p.token,"{\"title\":\"同步目标\"}",201));UUID task=id(postJson("/api/v1/families/"+p.family+"/goals/"+goal+"/tasks",p.token,"{\"title\":\"读一页\",\"category\":\"READING\",\"difficulty\":\"EASY\",\"expectedMinutes\":5}",201));String childToken=text(postJson("/api/v1/auth/child-sessions",p.token,"{\"childId\":\""+child+"\"}",201),"data","token");String sync="/api/v1/families/"+p.family+"/children/"+child+"/sync";mvc.perform(get(sync).header("Authorization",bearer(p.token))).andExpect(status().isOk()).andExpect(jsonPath("$.data.childName").value("同步孩子")).andExpect(jsonPath("$.data.tasks[0].status").value("TODO"));mvc.perform(post("/api/v1/families/"+p.family+"/children/"+child+"/tasks/"+task+"/completions").header("Authorization",bearer(childToken)).header("Idempotency-Key","stage8-submit").contentType(MediaType.APPLICATION_JSON).content("{\"evidenceNote\":\"完成\"}")).andExpect(status().isCreated());mvc.perform(get(sync).header("Authorization",bearer(childToken))).andExpect(status().isOk()).andExpect(jsonPath("$.data.tasks[0].status").value("SUBMITTED")).andExpect(jsonPath("$.data.tasks[0].latestCompletionId").isNotEmpty()).andExpect(jsonPath("$.data.pendingReviews").value(1));mvc.perform(get(sync).header("Authorization",bearer(other.token))).andExpect(status().isNotFound());}
 private MvcResult postJson(String url,String token,String body,int expected)throws Exception{return mvc.perform(post(url).header("Authorization",bearer(token)).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().is(expected)).andReturn();}private Session bootstrap(String name,String pin)throws Exception{MvcResult r=mvc.perform(post("/api/v1/auth/bootstrap").contentType(MediaType.APPLICATION_JSON).content("{\"familyName\":\""+name+"\",\"parentName\":\"家长\",\"pin\":\""+pin+"\"}")).andExpect(status().isCreated()).andReturn();return new Session(UUID.fromString(text(r,"data","familyId")),text(r,"data","session","token"));}private UUID id(MvcResult r)throws Exception{return UUID.fromString(text(r,"data","id"));}private String text(MvcResult r,String...path)throws Exception{JsonNode n=json.readTree(r.getResponse().getContentAsString());for(String p:path)n=n.path(p);return n.asText();}private static String bearer(String t){return "Bearer "+t;}private record Session(UUID family,String token){}
}
